// Curated knowledge for the App AI Assistant on the two Kitchen Tool pages:
//   /kitchen-tool/       (couples)  → mode 'tool-couples'
//   /kitchen-tool-solo/  (solo)     → mode 'tool-solo'
//
// The autogenerated _chatKnowledge.js cannot describe these pages (the build
// extractor strips Astro components), so this file is maintained by hand and
// mirrors the actual behaviour of src/components/tool/*.astro and
// src/lib/{kitchen-store,tool-store,pantry-parse,tdee}.ts.

export function buildToolSections(audience) {
  const isCouples = audience === 'couples';
  const isSolo = audience === 'solo';
  const page = isSolo ? '/kitchen-tool-solo/' : '/kitchen-tool/';
  const s = [];

  s.push({
    source: page,
    tool: true,
    overview: true,
    title: isSolo ? 'This page — the Kitchen Tool (solo version)' : 'This page — the Kitchen Tool (couples version)',
    text: isSolo
      ? 'This page is the free CookTwo Kitchen Tool (solo version) — an interactive demo of the app\u2019s engine room for one person. It has four tabs: Shopping list ("My shopping list"), Pantry ("My kitchen"), Your plate (daily calorie target), and Your diet. Everything runs entirely in your browser: typing your list sorts it, and no account is needed. AI meal generation itself lives in the full CookTwo app.'
      : 'This page is the free CookTwo Kitchen Tool (couples version) — an interactive demo of the app\u2019s engine room for two people. It has four tabs: Shopping list ("Our shopping list"), Pantry ("Our kitchen"), Two plates (a daily calorie target for each partner), and Diet match (whether both diets can share one meal). Everything runs entirely in your browser: typing your list sorts it, and no account is needed. AI meal generation itself lives in the full CookTwo app.',
  });

  s.push({
    source: page,
    tool: true,
    overview: true,
    title: 'Tabs of this tool',
    text: isSolo
      ? 'The tool has four tabs across the top of the card: 1) Shopping list, 2) Pantry, 3) Your plate, 4) Your diet. Click a tab to switch; each tab keeps its own data.'
      : 'The tool has four tabs across the top of the card: 1) Shopping list, 2) Pantry, 3) Two plates, 4) Diet match. Click a tab to switch; each tab keeps its own data.',
  });

  s.push({
    source: page,
    tool: true,
    title: 'How the shopping list works',
    text: isCouples
      ? 'Type exactly what you need in plain language — "Milk, 2 loaves of bread, dishwasher tablets" — and separate items with commas. Each item is parsed into name, quantity, unit and brand, then sorted into aisle categories: Produce, Meat, Dairy, Pantry, Household, Personal Care. Tick items off as you shop (the counter shows "in the trolley"). "Move checked to pantry" moves ticked food items into the Pantry tab (non-food items stay on the list — they are flagged "not a food item"). "Clear list" removes everything after a confirmation. Items are marked with a green dot for Partner 1 or terracotta dot for Partner 2, and an "Adding as Partner 1 / Partner 2" switch controls who new items are attributed to. The list saves automatically in this browser.'
      : 'Type exactly what you need in plain language — "Milk, 2 loaves of bread, dishwasher tablets" — and separate items with commas. Each item is parsed into name, quantity, unit and brand, then sorted into aisle categories: Produce, Meat, Dairy, Pantry, Household, Personal Care. Tick items off as you shop (the counter shows "in the trolley"). "Move checked to pantry" moves ticked food items into the Pantry tab (non-food items stay on the list — they are flagged "not a food item"). "Clear list" removes everything after a confirmation. The list saves automatically in this browser.',
  });

  s.push({
    source: page,
    tool: true,
    title: 'How the pantry works',
    text: isCouples
      ? 'The Pantry tab ("Our kitchen") takes the same natural-language input — "1 litre whole milk, 250g Swiss cheddar, half an onion" — and sorts everything into categories automatically. If an item lands in the wrong category you can tap its category button and correct it. Individual items can be removed with the cross. The pantry is saved in this browser. In the full CookTwo app the pantry is what the AI reads to invent meals, so keeping it up to date is what makes AI dinner suggestions work.'
      : 'The Pantry tab ("My kitchen") takes the same natural-language input — "1 litre whole milk, 250g Swiss cheddar, half an onion" — and sorts everything into categories automatically. If an item lands in the wrong category you can tap its category button and correct it. Individual items can be removed with the cross. The pantry is saved in this browser. In the full CookTwo app the pantry is what the AI reads to invent meals, so keeping it up to date is what makes AI dinner suggestions work.',
  });

  s.push({
    source: page,
    tool: true,
    title: isSolo ? 'How Your plate (daily calories) works' : 'How Two plates (daily calories) works',
    text: isCouples
      ? 'The Two plates tab calculates each partner\u2019s daily calorie target per plate with the same math the app uses: the Mifflin-St Jeor equation for BMR with an activity multiplier, then a goal adjustment of −500 kcal for losing weight, 0 for maintaining, or +300 kcal for gaining. It is fully automatic — just fill in the fields and the number appears; there is nothing to log and nothing to work out yourself. Enter each partner\u2019s weight, height, age, gender, activity level (sedentary, light, moderate, active, very active) and goal — the plate target updates live. Partner 1 is shown in sage green, Partner 2 in terracotta. When both targets are set, the tool sums up the difference — for example "X eats 460 kcal and Y eats 720 kcal — a 57% bigger plate. Same pan, same timing." There is a Metric / Imperial switch for kg/cm vs lb/ft-in.'
      : 'The Your plate tab calculates your daily calorie target with the same math the app uses: the Mifflin-St Jeor equation for BMR with an activity multiplier, then a goal adjustment of −500 kcal for losing weight, 0 for maintaining, or +300 kcal for gaining. It is fully automatic — just fill in the fields and the number appears; there is nothing to log and nothing to work out yourself. Enter your weight, height, age, gender, activity level (sedentary, light, moderate, active, very active) and goal — the target updates live, and the summary explains the number. There is a Metric / Imperial switch for kg/cm vs lb/ft-in.',
  });

  s.push({
    source: page,
    tool: true,
    title: isSolo ? 'How Your diet works' : 'How Diet match works',
    text: isCouples
      ? 'Diet match lets each partner pick a diet from CookTwo\u2019s 22-diet catalogue — including Mediterranean, keto, paleo, vegan, vegetarian, pescatarian, gluten-free, DASH, MIND, high-protein and more, grouped into categories like Balanced, Low-Carb, Plant-Based, Macronutrient-Focused, Therapeutic and Elimination. The tool then shows whether you can cook one meal together using the app\u2019s own compatibility rules: an easy match, an adaptable match (with the adaptation needed), or a hard conflict (suggesting separate meals with a shared base). This is the same compatibility engine the app uses to plan shared meals.'
      : 'Your diet lets you pick from CookTwo\u2019s 22-diet catalogue — including Mediterranean, keto, paleo, vegan, vegetarian, pescatarian, gluten-free, DASH, MIND, high-protein and more, grouped into categories like Balanced, Low-Carb, Plant-Based, Macronutrient-Focused, Therapeutic and Elimination — and shows what each diet allows and what it restricts. This is the same catalogue the app uses to plan meals.',
  });

  s.push({
    source: page,
    tool: true,
    title: 'Where the tool\u2019s data is stored',
    text: isSolo
      ? 'Nothing on this page is uploaded anywhere — it is a single-person tool with nothing shared with anyone. The shopping list, pantry and profile inputs are stored only in this browser (localStorage), saved automatically, and kept separate from the other Kitchen Tool page. No account, no sign-up, no server — close the tab and come back later and the data is still there on the same browser. Clearing browser data (or using private mode) resets it. Cloud sync is not part of this tool; that only exists in the separate full CookTwo app for couples.'
      : 'Nothing on this page is uploaded anywhere. The shopping list, pantry and profile inputs are stored only in this browser (localStorage), saved automatically, and kept separate from the other Kitchen Tool page. No account, no sign-up, no server — close the tab and come back later and the data is still there on the same browser. Clearing browser data (or using private mode) resets it. The full CookTwo app adds cloud sync between partners\u2019 phones on top of this.',
  });

  s.push({
    source: page,
    tool: true,
    title: 'Tool vs the full CookTwo app',
    text: isSolo
      ? 'This page is the free single-person preview of the app\u2019s "engine room": parsing, sorting, pantry, calorie math and diet browsing. It is a standalone tool — no account, nothing shared with anyone. What this page does NOT do is generate meals with AI — that lives in the full CookTwo app (cooktwo.app), a collaborative nutrition product designed for couples (two partners, one shared kitchen, one recipe plated two ways). The app also adds weekly meal plans, a saved recipe library, real-time sync between partners\u2019 phones, push notifications and offline support. You can get early access from the buttons on this page or at https://cooktwo.com/.'
      : 'This page is the free preview of the app\u2019s "engine room": parsing, sorting, pantry, calorie math and diet compatibility. What this page does NOT do is generate meals with AI — that lives in the full CookTwo app (cooktwo.app), together with weekly meal plans, a saved recipe library, real-time sync between partners, push notifications and offline support. The app is a collaborative adaptive nutrition app for couples: one recipe, plated two different ways for each partner\u2019s goals. You can get early access from the buttons on this page or at https://cooktwo.com/.',
  });

  s.push({
    source: page,
    tool: true,
    title: 'Troubleshooting the tool',
    text: 'If an item is sorted into the wrong category, tap its category and pick the right one. If an item is labelled "not a food item", it cannot be moved to the pantry — only food moves. If your list seems to have disappeared, your browser may be blocking site storage (private windows do this) — it still works for the session. For the parser, "quantity + unit + name" works best: "2 cups flour", "500g chicken breast", "1 litre milk". Obvious brand names are recognised too. If something really looks broken, use the contact page at https://cooktwo.com/contact/.',
  });

  return s;
}
